declare_lint ! { #[doc = " The `unreachable_pub` lint triggers for `pub` items not reachable from other crates - that"] #[doc = " means neither directly accessible, nor reexported (with `pub use`), nor leaked through"] #[doc = " things like return types (which the [`unnameable_types`] lint can detect if desired)."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " #![deny(unreachable_pub)]"] #[doc = " mod foo {"] #[doc = "     pub mod bar {"] #[doc = ""] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " The `pub` keyword both expresses an intent for an item to be publicly available, and also"] #[doc = " signals to the compiler to make the item publicly accessible. The intent can only be"] #[doc = " satisfied, however, if all items which contain this item are *also* publicly accessible."] #[doc = " Thus, this lint serves to identify situations where the intent does not match the reality."] #[doc = ""] #[doc = " If you wish the item to be accessible elsewhere within the crate, but not outside it, the"] #[doc = " `pub` visibility is recommended to be used instead. This more clearly expresses the"] #[doc = " intent that the item is only visible within its own crate."] #[doc = ""] #[doc = " This lint is \"allow\" by default because it will trigger for a large amount of existing Rust code."] #[doc = " Eventually it is desired for this to become warn-by-default."] #[doc = ""] #[doc = " [`unnameable_types`]: #unnameable-types"] pub UNREACHABLE_PUB , Allow , "`pub` items not reachable from crate root" }